    const parts = raw.split('.');
    if (parts.length !== 3 || !/^[A-Za-z0-9_-]{2,8192}$/.test(parts[1])) return output;
    const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
