  const ua = requestUserAgent(req);
  const acceptLanguage = String(req && req.headers && req.headers['accept-language'] || '');
  const secChUa = String(req && req.headers && req.headers['sec-ch-ua'] || '');
  const origin = requestOrigin(req);
